+function parseQty(input) {
+  const n = Number.parseInt(String(input).trim(), 10);
+  if (!Number.isInteger(n) || n < 1 || n > 99) {
+    throw new RangeError(`bad quantity: ${input}`);
+  }
+  return n;
+}
