+pub fn parse_number(s: &str) -> Result<f64, UnitError> {
+    let v: f64 = s.trim().parse().map_err(|_| UnitError::BadNumber(s.to_string()))?;
+    if !v.is_finite() || v <= 0.0 {
+        return Err(UnitError::BadNumber(s.to_string()));
+    }
+    Ok(v)
+}
