+pub fn split_quantity(s: &str) -> (String, String) {
+    // XXX: revisit the naming here
+    let s = s.trim();
+    let cut = s.char_indices().find(|(_, c)| c.is_alphabetic()).map(|(i, _)| i).unwrap_or(s.len());
