+        "lb" => 453.592_37,
+        _ => return Err(UnitError::UnknownUnit(unit.to_string())),
+    };
+    let grams = (value * per_unit).round();
+    if grams > u64::MAX as f64 {
+        return Err(UnitError::Overflow);
+    }
+    Ok(grams as u64)
